//! Fixture parity tests for the ACE-Step 1.5 port.
//!
//! Tiny fixtures live in `testdata/ace_step15_vae/`, regenerated by
//! `tools/gen_ace_step15_vae_fixtures.py` from diffusers 0.43.0 on the
//! CPU in f32. The real-checkpoint test is ignored: point
//! TURBOSPARK_ACE_STEP15_VAE at the checkpoint `vae/` directory and
//! TURBOSPARK_ACE_STEP15_VAE_REF at the `--real` output directory.
//! Tests never download.

use std::path::{Path, PathBuf};

use super::vae::{OobleckConfig, OobleckVae};
use turbospark_model_io::safetensors::SafetensorsFile;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/ace_step15_vae")
        .join(name)
}

pub(super) fn read_npy(path: &Path) -> (Vec<usize>, Vec<f32>) {
    let bytes = std::fs::read(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    assert_eq!(&bytes[..6], b"\x93NUMPY");
    let header_len = u16::from_le_bytes([bytes[8], bytes[9]]) as usize;
    let header = std::str::from_utf8(&bytes[10..10 + header_len]).unwrap();
    assert!(
        header.contains("'<f4'"),
        "{}: not little-endian f32",
        path.display()
    );
    assert!(header.contains("'fortran_order': False"));
    let start = header.find('(').unwrap() + 1;
    let end = header[start..].find(')').unwrap() + start;
    let shape: Vec<usize> = header[start..end]
        .split(',')
        .filter_map(|p| p.trim().parse::<usize>().ok())
        .collect();
    let data = bytes[10 + header_len..]
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    (shape, data)
}

/// Max absolute difference divided by max(1, max |reference|).
pub(super) fn rel_err(got: &[f32], want: &[f32]) -> f32 {
    assert_eq!(got.len(), want.len(), "length mismatch");
    let scale = want.iter().fold(1.0f32, |m, v| m.max(v.abs()));
    got.iter()
        .zip(want)
        .map(|(a, b)| (a - b).abs())
        .fold(0.0f32, f32::max)
        / scale
}

fn load_tiny() -> OobleckVae {
    let text = std::fs::read_to_string(testdata("tiny_config.json")).unwrap();
    let config = OobleckConfig::from_json(&serde_json::from_str(&text).unwrap()).unwrap();
    let file = SafetensorsFile::open(&testdata("tiny_weights.safetensors")).unwrap();
    OobleckVae::load(config, &file).unwrap()
}

/// Encodes, samples with the recorded noise, and decodes one case,
/// returning the worst relative error per stage.
fn check_case(vae: &OobleckVae, dir: &Path, tag: &str) -> [f32; 4] {
    let file = |s: &str| dir.join(format!("{tag}_{s}.npy"));
    let (ashape, audio) = read_npy(&file("audio"));
    let (lshape, mean) = read_npy(&file("mean"));
    let (_, std) = read_npy(&file("std"));
    let (_, noise) = read_npy(&file("noise"));
    let (_, sample) = read_npy(&file("sample"));
    let (dshape, decoded) = read_npy(&file("decoded"));

    let moments = vae.encode(&audio, ashape[1]).unwrap();
    assert_eq!(moments.frames, lshape[1], "{tag}: latent frames");
    let got_sample = moments.sample(&noise).unwrap();
    let (wave, samples) = vae.decode(&sample, lshape[1]).unwrap();
    assert_eq!(samples, dshape[1], "{tag}: decoded length");
    [
        rel_err(&moments.mean, &mean),
        rel_err(&moments.std, &std),
        rel_err(&got_sample, &sample),
        rel_err(&wave, &decoded),
    ]
}

#[test]
fn config_defaults_match_diffusers() {
    let c = OobleckConfig::from_json(&serde_json::json!({})).unwrap();
    assert_eq!(c, OobleckConfig::default());
    assert_eq!(c.hop_length(), 2048);
}

#[test]
fn shipped_vae_config_parses() {
    // vae/config.json at the pinned checkpoint revision.
    let c = OobleckConfig::from_json(&serde_json::json!({
        "_class_name": "AutoencoderOobleck",
        "_diffusers_version": "0.32.2",
        "audio_channels": 2,
        "channel_multiples": [1, 2, 4, 8, 16],
        "decoder_channels": 128,
        "decoder_input_channels": 64,
        "downsampling_ratios": [2, 4, 4, 6, 10],
        "encoder_hidden_size": 128,
        "sampling_rate": 48000
    }))
    .unwrap();
    assert_eq!(c.hop_length(), 1920);
    assert_eq!(c.latent_channels(), 64);
    assert_eq!(c.sampling_rate / c.hop_length() as u32, 25);
}

#[test]
fn config_rejects_inconsistent_geometry() {
    for bad in [
        serde_json::json!({"downsampling_ratios": [2, 4], "channel_multiples": [1, 2, 4]}),
        serde_json::json!({"encoder_hidden_size": 128, "decoder_input_channels": 32}),
        serde_json::json!({"downsampling_ratios": [0, 4, 4, 8, 8]}),
        serde_json::json!({"downsampling_ratios": []}),
        serde_json::json!({"channel_multiples": [1, 2, 4, 8, 4096]}),
    ] {
        assert!(OobleckConfig::from_json(&bad).is_err(), "accepted {bad}");
    }
}

#[test]
fn rejects_bad_shapes() {
    let vae = load_tiny();
    let hop = vae.config().hop_length();
    assert!(vae.encode(&vec![0.0; 2 * hop - 1], hop).is_err());
    assert!(vae.encode(&vec![0.0; 2 * (hop - 1)], hop - 1).is_err());
    assert!(vae.decode(&[0.0; 7], 2).is_err());
    assert!(vae.decode(&[], 0).is_err());
    let m = vae.encode(&vec![0.1; 2 * hop], hop).unwrap();
    assert!(m.sample(&[0.0]).is_err());
}

/// Tolerance from the measured f32 gap to PyTorch on these fixtures
/// (worst stage 2.7e-6 relative on M4 Max, case b sample), with headroom
/// for summation-order differences across hosts. Mutating the dilations,
/// the Snake beta exp, or the residual add fails it by 5e-1 or more.
const TINY_TOL: f32 = 1e-5;

#[test]
fn tiny_matches_diffusers() {
    let vae = load_tiny();
    let dir = testdata("");
    for tag in ["a", "b"] {
        let errs = check_case(&vae, &dir, tag);
        eprintln!(
            "tiny {tag}: mean {:.2e} std {:.2e} sample {:.2e} decode {:.2e}",
            errs[0], errs[1], errs[2], errs[3]
        );
        for (stage, e) in ["mean", "std", "sample", "decode"].iter().zip(errs) {
            assert!(e <= TINY_TOL, "{tag} {stage}: relative error {e:.3e}");
        }
    }
}

/// Real checkpoint, 2 s stereo at 48 kHz, f32 on both sides. Measured
/// worst stage 4.8e-6 relative (mean) on M4 Max; the bound keeps about
/// 4x headroom, like the tiny gate.
#[test]
#[ignore = "needs TURBOSPARK_ACE_STEP15_VAE and TURBOSPARK_ACE_STEP15_VAE_REF"]
fn real_checkpoint_matches_diffusers() {
    let (Ok(vae_dir), Ok(ref_dir)) = (
        std::env::var("TURBOSPARK_ACE_STEP15_VAE"),
        std::env::var("TURBOSPARK_ACE_STEP15_VAE_REF"),
    ) else {
        panic!("set TURBOSPARK_ACE_STEP15_VAE and TURBOSPARK_ACE_STEP15_VAE_REF");
    };
    let vae_dir = PathBuf::from(vae_dir);
    let text = std::fs::read_to_string(vae_dir.join("config.json")).unwrap();
    let config = OobleckConfig::from_json(&serde_json::from_str(&text).unwrap()).unwrap();
    let file = SafetensorsFile::open(&vae_dir.join("diffusion_pytorch_model.safetensors")).unwrap();
    let vae = OobleckVae::load(config, &file).unwrap();
    let errs = check_case(&vae, Path::new(&ref_dir), "real");
    eprintln!(
        "real: mean {:.2e} std {:.2e} sample {:.2e} decode {:.2e}",
        errs[0], errs[1], errs[2], errs[3]
    );
    for (stage, e) in ["mean", "std", "sample", "decode"].iter().zip(errs) {
        assert!(e <= 2e-5, "{stage}: relative error {e:.3e}");
    }
}

/// Timing only: host decode and encode of `ACE_STEP15_SECONDS` (default
/// 10) on the real VAE. Not a frozen benchmark row.
#[test]
#[ignore = "timing; needs TURBOSPARK_ACE_STEP15_VAE"]
fn real_vae_cpu_timing() {
    let vae_dir = PathBuf::from(std::env::var("TURBOSPARK_ACE_STEP15_VAE").unwrap());
    let seconds: usize = std::env::var("ACE_STEP15_SECONDS")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(10);
    let text = std::fs::read_to_string(vae_dir.join("config.json")).unwrap();
    let config = OobleckConfig::from_json(&serde_json::from_str(&text).unwrap()).unwrap();
    let file = SafetensorsFile::open(&vae_dir.join("diffusion_pytorch_model.safetensors")).unwrap();
    let vae = OobleckVae::load(config.clone(), &file).unwrap();
    let frames = seconds * 25;
    let latents: Vec<f32> = (0..64 * frames)
        .map(|i| ((i as f32) * 0.37).sin())
        .collect();
    let t = std::time::Instant::now();
    let (wave, samples) = vae.decode(&latents, frames).unwrap();
    let decode = t.elapsed();
    let t = std::time::Instant::now();
    let m = vae.encode(&wave, samples).unwrap();
    let encode = t.elapsed();
    assert_eq!(m.frames, frames);
    eprintln!(
        "vae cpu: {seconds} s ({frames} frames, {samples} samples): decode {:.2} s, encode {:.2} s",
        decode.as_secs_f64(),
        encode.as_secs_f64()
    );
}

/// A host stand-in for a device backend: weights stay as F32 and
/// convolutions run through `ops::conv1d`. It exercises the device form
/// of every VAE conv (including the phase split of transposed convs)
/// without a GPU, so the decomposition is gated on any host.
struct HostConvBackend;
struct HostConvWeight {
    data: Vec<f32>,
}

impl crate::backend::ComputeBackend for HostConvBackend {
    fn load_weight(
        &self,
        data: crate::backend::WeightData<'_>,
    ) -> crate::Result<std::rc::Rc<dyn crate::backend::DeviceWeight>> {
        assert_eq!(data.encoding, crate::backend::WeightEncoding::F32);
        let floats = data
            .bytes
            .chunks_exact(4)
            .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
            .collect();
        Ok(std::rc::Rc::new(HostConvWeight { data: floats }))
    }
    fn attention(
        &self,
        _q: &[f32],
        _k: &[f32],
        _v: &[f32],
        _s: crate::backend::AttentionShape,
        _d: crate::backend::DType,
    ) -> crate::Result<Vec<f32>> {
        unreachable!("the VAE has no attention")
    }
}

impl crate::backend::DeviceWeight for HostConvWeight {
    fn linear(
        &self,
        _x: &[f32],
        _b: Option<&[f32]>,
        _r: usize,
        _i: usize,
        _o: usize,
        _d: crate::backend::DType,
    ) -> crate::Result<Vec<f32>> {
        unreachable!("the VAE has no linears")
    }
    fn embedding(&self, _ids: &[i32], _w: usize) -> crate::Result<Vec<f32>> {
        unreachable!("the VAE has no embeddings")
    }
    fn convolution(
        &self,
        x: &[f32],
        bias: Option<&[f32]>,
        s: crate::backend::ConvShape,
        _d: crate::backend::DType,
    ) -> crate::Result<Vec<f32>> {
        // The device form is always forward (transposed convs arrive as
        // phase convs).
        assert!(!s.transpose, "device form must not be transposed");
        Ok(crate::ops::conv1d(
            x,
            &self.data,
            bias,
            s.input_channels,
            s.output_channels,
            s.kernel,
            s.stride,
            s.padding,
            s.dilation,
            1,
        ))
    }
}

/// The device form (phase-split transposed convs) against the direct
/// host form and the reference. Measured: phase vs direct about 1e-7
/// relative on the tiny fixtures.
#[test]
fn device_form_matches_host_form() {
    let host = load_tiny();
    let mut device = load_tiny();
    device.attach_backend(&HostConvBackend).unwrap();
    let dir = testdata("");
    for tag in ["a", "b"] {
        let (lshape, sample) = read_npy(&dir.join(format!("{tag}_sample.npy")));
        let (want, _) = host.decode(&sample, lshape[1]).unwrap();
        let (got, _) = device.decode(&sample, lshape[1]).unwrap();
        let e = rel_err(&got, &want);
        eprintln!("device form {tag}: decode vs host {e:.2e}");
        assert!(
            e <= 1e-6,
            "{tag}: phase-split decode differs from direct by {e:.3e}"
        );
        let errs = check_case(&device, &dir, tag);
        for (stage, e) in ["mean", "std", "sample", "decode"].iter().zip(errs) {
            assert!(e <= TINY_TOL, "{tag} {stage}: relative error {e:.3e}");
        }
    }
}

/// Tiled decode keeps each window's core: with an overlap that covers the
/// decoder's receptive field (about 13 latent frames on the tiny model:
/// the k7 input conv, then the dilated residual units at each rate) it
/// must equal the untiled decode, and it refuses a zero chunk.
#[test]
fn tiled_decode_matches_untiled() {
    let vae = load_tiny();
    let frames = 80;
    let latents: Vec<f32> = (0..vae.config().latent_channels() * frames)
        .map(|i| ((i as f32) * 0.37).sin())
        .collect();
    let (whole, n) = vae.decode(&latents, frames).unwrap();
    let (tiled, m) = vae.decode_tiled(&latents, frames, 48, 16).unwrap();
    assert_eq!(n, m);
    let e = rel_err(&tiled, &whole);
    eprintln!("tiled 48/16 vs untiled: {e:.2e}");
    assert_eq!(
        e, 0.0,
        "tiled decode must be exact when overlap covers the receptive field"
    );
    assert!(vae.decode_tiled(&latents, frames, 0, 4).is_err());
    // chunk <= 2 x overlap: upstream halves the overlap (16 -> 8) instead
    // of failing.
    let (shrunk, k) = vae.decode_tiled(&latents, frames, 20, 16).unwrap();
    assert_eq!((shrunk.len(), k), (whole.len(), n));
    // Too little overlap: seams appear (guards against a decode_tiled
    // that silently ignores its windows).
    let (narrow, _) = vae.decode_tiled(&latents, frames, 9, 0).unwrap();
    assert!(
        rel_err(&narrow, &whole) > 0.0,
        "zero overlap should leave seams"
    );
}
